def gcd(a, b):
    """Calculate the greatest common divisor of two integers."""
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    """Calculate the least common multiple of two integers."""
    return a * b // gcd(a, b)

def num_squares(n):
    """
    Calculate the minimum number of perfect squares that sum to n.

    Args:
        n: Positive integer

    Returns:
        Minimum number of perfect squares that sum to n
    """
    if n < 0:
        return 0  # Not a valid case according to the problem
    if n == 1:
        return 1

    # Try all possible squares that can be subtracted
    result = n  # Maximum possible value
    i = 1
    while i * i <= n:
        remainder = n - i * i
        if remainder >= 0:
            # Calculate the number of squares needed for the remainder
            result = min(result, 1 + num_squares(remainder))
        i += 1
    return result

