def permute(nums):
    if len(nums) == 0:
        return [[]]
    result = []
    for i in range(len(nums)):
        x = nums[i]
        remaining = nums[:i] + nums[i+1:]
        for p in permute(remaining):
            result.append([x] + p)
    return result

