def main():
    # Read input grid
    grid = []
    for line in sys.stdin:
        stripped_line = line.strip()
        if stripped_line:
            grid.append([int(c) for c in stripped_line])

    if not grid:
        print(0)
        return

    rows = len(grid)
    cols = len(grid[0])
    visited = [[False for _ in range(cols)] for _ in range(rows)]
    count = 0

    # Traverse each cell in the grid
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1 and not visited[i][j]:
                # BFS to find entire component
                queue = deque()
                queue.append((i, j))
                visited[i][j] = True
                is_border = False

                # Main BFS loop
                while queue:
                    x, y = queue.popleft()
                    # Check if current cell is on the border
                    if x == 0 or x == rows - 1 or y == 0 or y == cols - 1:
                        is_border = True
                    # Explore neighbors
                    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < rows and 0 <= ny < cols:
                            if grid[nx][ny] == 1 and not visited[nx][ny]:
                                visited[nx][ny] = True
                                queue.append((nx, ny))

                # If component is not touching the border
                if not is_border:
                    count += 1

    print(count)

